pub fn inverse_iso16757_mutation(mutation: &Iso16757Mutation, base: &Iso16757Snapshot) -> Vec<Iso16757Mutation> {
    <Iso16757Mutation as protocol::Mutation<Iso16757Snapshot>>::inverse(mutation, base)
