    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        for (keyword, spec) in <Self as dsl::DslVariants>::variants() {
            let prefix = format!("{keyword} ");
            if line == keyword || line.starts_with(&prefix) {
                let body = line[keyword.len()..].trim_start();
                return <Self as dsl::DslVariants>::from_named_record(&keyword, &dsl::parse(body, &(spec.ordinary)(), &dsl::ParseOptions { limits: semio_framework_diagnostic::Limits::default(), mode: dsl::SourceMode::Inline })?);
            }
        }
        Err(dsl::__rt::field_error(format!("unknown operation line '{line}'")))
    }
